@* A single product card displaying image, name, price, rating, stock status, and add-to-cart *@

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h3 class="product-name">@Product.Name</h3>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <p class="product-rating">@GetStarRating(Product.Rating)</p>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<int> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product.Id);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product.Id);
    }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        int empty = 5 - filled;
        return new string('★', filled) + new string('☆', empty);
    }
}

@if (Products is null || Products.Count == 0)
{
    <div class="empty-results">
        <p>No products found matching your criteria.</p>
    </div>
}
else
{
    <div class="product-grid">
        @foreach (var product in Products)
        {
            <ProductCard Product="product"
                         OnProductSelected="OnProductSelected"
                         OnAddToCart="OnAddToCart" />
        }
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = default!;

    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<int> OnAddToCart { get; set; }
}

@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page">
    @if (_error is not null)
    {
        <div class="error-message">
            <p>Something went wrong: @_error</p>
            <button @onclick="LoadDataAsync">Retry</button>
        </div>
    }
    else if (_loading)
    {
        <div class="loading">
            <p>Loading products...</p>
        </div>
    }
    else
    {
        <div class="catalog-layout">
            <aside class="catalog-sidebar">
                <CatalogFilters Categories="_categories"
                                CurrentFilter="_filter"
                                OnFiltersApplied="HandleFiltersApplied" />
            </aside>
            <main class="catalog-main">
                <CatalogToolbar SortBy="@_sortBy"
                                TotalCount="_totalCount"
                                Page="_currentPage"
                                PageSize="PageSize"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="_products"
                             OnProductSelected="OnProductSelected"
                             OnAddToCart="OnAddToCart" />

                @if (_totalPages > 1)
                {
                    <CatalogPagination CurrentPage="_currentPage"
                                       TotalPages="_totalPages"
                                       OnPageChanged="HandlePageChanged" />
                }
            </main>
        </div>
    }
</div>

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<int> OnAddToCart { get; set; }

    private List<Product> _products = new();
    private List<string> _categories = new();
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalCount;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            var result = await productsTask;
            _products = result.Items;
            _totalCount = result.TotalCount;
            _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _error = null;
            _loading = true;

            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
            _products = result.Items;
            _totalCount = result.TotalCount;
            _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }
}

