namespace sv_8543a8d3c3244e13873877bd9bc4cbb2;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

.catalog-page {
    padding: 1rem;
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

/* Filters */
.catalog-filters h2 {
    margin-top: 0;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

.filter-section label input[type="number"] {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
}

.btn-apply {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-clear {
    background: transparent;
}

/* Toolbar */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.toolbar-sort select {
    padding: 0.3rem 0.5rem;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.5rem;
}

.product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
}

.product-image {
    background: #f5f5f5;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.85rem;
}

.product-info {
    padding: 1rem;
}

.product-name {
    margin: 0 0 0.5rem;
    font-size: 1rem;
}

.product-price {
    font-weight: bold;
    color: #2e7d32;
    margin: 0 0 0.3rem;
}

.product-rating {
    color: #f9a825;
    margin: 0 0 0.5rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #ef5350;
    color: white;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-add-to-cart:disabled {
    background: #bdbdbd;
    cursor: not-allowed;
}

/* Pagination */
.catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.3rem;
    margin-top: 2rem;
    padding: 1rem 0;
}

.catalog-pagination button {
    padding: 0.4rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

.catalog-pagination button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.catalog-pagination button.page-active {
    background: #1976d2;
    color: white;
    border-color: #1976d2;
}

/* States */
.loading,
.error-message,
.empty-results {
    text-align: center;
    padding: 3rem 1rem;
}

.error-message {
    color: #d32f2f;
}

.error-message button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    border: 1px solid #d32f2f;
    border-radius: 4px;
    background: white;
    color: #d32f2f;
    cursor: pointer;
}

